    const sel = document.getElementById('selTec');
    const btnSelect = document.getElementById('btnSelect');
    const selInfo = document.getElementById('selInfo');
    const lblTec = document.getElementById('lblTec');
    const btnCambiar = document.getElementById('btnCambiar');

    const frmWrap = document.getElementById('frmWrap');
    const modeBadge = document.getElementById('modeBadge');
    const lblPass1 = document.getElementById('lblPass1');
    const lblPass2 = document.getElementById('lblPass2');
    const pass1 = document.getElementById('pass1');
    const pass2 = document.getElementById('pass2');
    const btnGuardar = document.getElementById('btnGuardar');
    const btnCancelar = document.getElementById('btnCancelar');
    const msg = document.getElementById('msg');


    const plantaWrap     = document.getElementById('plantaWrap');
    const tgPlanta       = document.getElementById('tgPlanta');
    const inpPlanta      = document.getElementById('inpPlanta');
    const btnSavePlanta  = document.getElementById('btnSavePlanta');
    const btnCancelPlanta= document.getElementById('btnCancelPlanta');
    const msgPlanta      = document.getElementById('msgPlanta');

    let plantaOriginal = ''; // valor que vino del servidor para comparar cambios

    // Poblamos select
    const list = (RAW?.GetMuestra_Tecnicos_Almacen_AgendaResult || []).slice().sort((a,b)=>String(a.tecnico).localeCompare(String(b.tecnico),'es'));

    // ===== Helpers SweetAlert2 =====
    function showAlert(title, text, icon='info') {
    Swal.fire({
        title, text, icon,
        confirmButtonColor: '#0d6efd',
        confirmButtonText: 'OK'
    });
    }

    function confirmAction(msg) {
    return Swal.fire({
        title: '¿Confirmar acción?',
        text: msg || '¿Deseas continuar?',
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'Sí',
        cancelButtonText: 'Cancelar',
        confirmButtonColor: '#0d6efd',
    }).then(r => r.isConfirmed);
    }

    
    for (const it of list) {
        const opt = document.createElement('option');
        opt.value = it.clv_tecnico;
        opt.textContent = `${it.tecnico} — ${it.clv_tecnico}`;
        opt.dataset.nombre = it.tecnico;
        sel.appendChild(opt);
    }

    // Estado local
    let current = null; // { id, nombre, hasPassword }

    function uiSelectMode(on){
        sel.disabled = on;
        btnSelect.classList.toggle('d-none', on);
        selInfo.classList.toggle('d-none', !on);
        frmWrap.classList.toggle('d-none', !on);
        if (on) frmWrap.classList.add('fade-slide','expanded');
    }

    function setFormMode(hasPass){
        modeBadge.textContent = hasPass ? 'Cambiar contraseña' : 'Crear contraseña';
        modeBadge.className = hasPass ? 'badge text-bg-warning' : 'badge text-bg-success';
        lblPass1.textContent = hasPass ? 'Nueva contraseña' : 'Crear contraseña';
        lblPass2.textContent = hasPass ? 'Confirmar nueva contraseña' : 'Confirmar contraseña';
        pass1.value = '';
        pass2.value = '';
        msg.className = 'alert d-none';
        msg.textContent = '';
    }

    async function postJSON(url, body){
        const resp = await fetch(url, {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body: JSON.stringify(body)
        });
        const j = await resp.json().catch(()=>({ok:false,message:'Respuesta inválida'}));
        if(!resp.ok || !j.ok) throw new Error(j.message || 'Operación fallida');
        return j;
    }

    // Cambiar de técnico
    btnCambiar.addEventListener('click', ()=>{
        current = null;
        uiSelectMode(false);
        frmWrap.classList.remove('expanded');
        msg.className = 'alert d-none'; msg.textContent='';
        sel.value = '';
    });

    // Guardar contraseña
    btnGuardar.addEventListener('click', async ()=>{
        if (!current?.id) return;

        const p1 = pass1.value.trim();
        const p2 = pass2.value.trim();

        if (!p1) { showAlert('Campo vacío', 'Debes escribir una contraseña.', 'warning'); return; }
        if (p1.length < 8) { showAlert('Contraseña corta', 'Debe tener al menos 8 caracteres.', 'warning'); return; }
        if (p1 !== p2) { showAlert('No coinciden', 'Las contraseñas no son iguales.', 'error'); return; }

        if (!(await confirmAction('¿Deseas guardar la nueva contraseña?'))) return;

        try{
            await postJSON('tech_actions.php', { action:'save_password', idtec: current.id, password: p1 });
            showAlert('Listo', 'Contraseña guardada correctamente.', 'success');
            pass1.value = '';
            pass2.value = '';
        }catch(e){
            showAlert('Error', e.message || 'No se pudo guardar la contraseña.', 'error');
        }
    });

    // Cancelar vuelve a estado inicial
    btnCancelar.addEventListener('click', ()=>{
        current = null;
        sel.value = '';
        uiSelectMode(false);
        msg.className = 'alert d-none'; msg.textContent='';
    });

    //Seleccionar Planta
    function plantaSetEnabled(on){
        inpPlanta.disabled = !on;
        btnSavePlanta.disabled = !on;
        btnCancelPlanta.disabled = !on;
    }
    function plantaReset(){
        tgPlanta.checked = false;
        inpPlanta.value = plantaOriginal || '';
        plantaSetEnabled(false);
        msgPlanta.className = 'alert d-none';
        msgPlanta.textContent = '';
    }

    // Cuando seleccionas técnico (AJUSTA el handler existente):
    // Seleccionar técnico (UNIFICADO)
    btnSelect.addEventListener('click', async ()=>{
    const id = parseInt(sel.value,10);
    if (!id) { showAlert('Elige un técnico', 'Selecciona un técnico del listado.', 'warning'); return; }
    const nombre = sel.options[sel.selectedIndex].dataset.nombre || '';

    try{
        // En el servidor: asegura existencia y retorna hasPassword + planta
        const j = await postJSON('tech_actions.php', { action:'select_tec', idtec:id, nombre:nombre });
        current = { id, nombre, hasPassword: !!j.hasPassword };

        // UI contraseña
        lblTec.textContent = `${nombre} — ${id}`;
        setFormMode(current.hasPassword);
        uiSelectMode(true);

        // UI planta
        plantaOriginal = (j.planta || '').trim();
        inpPlanta.value = plantaOriginal;
        plantaReset();                         // deshabilita por defecto
        plantaWrap.classList.remove('d-none'); // muestra tarjeta de Planta

    }catch(e){
        showAlert('Error', e.message || 'No se pudo cargar el técnico.', 'error');
    }
    });

    // Cambiar técnico (AJUSTA el handler existente):
    btnCambiar.addEventListener('click', ()=>{
        current = null;
        uiSelectMode(false);
        frmWrap.classList.remove('expanded');
        msg.className = 'alert d-none'; msg.textContent='';
        sel.value = '';

        // Planta: oculta y limpia
        plantaWrap.classList.add('d-none');
        plantaOriginal = '';
        plantaReset();
    });

    // Toggle Planta
    tgPlanta.addEventListener('change', ()=>{
        const on = tgPlanta.checked;
        plantaSetEnabled(on);
        if (!on) plantaReset();
    });

    // Cancelar Planta
    btnCancelPlanta.addEventListener('click', ()=>{
        plantaReset();
    });

    // Guardar Planta
    btnSavePlanta.addEventListener('click', async ()=>{
        if (!current?.id) return;

        const nuevo = (inpPlanta.value || '').trim();
        if (nuevo === plantaOriginal) { plantaReset(); return; }
        if (nuevo.length > 100) { showAlert('Demasiado largo', 'La planta no debe exceder 100 caracteres.', 'warning'); return; }

        if (!(await confirmAction('¿Deseas guardar la nueva planta?'))) return;

        try{
            await postJSON('tech_actions.php', { action:'save_planta', idtec: current.id, planta: nuevo });
            plantaOriginal = nuevo;
            showAlert('Guardado', 'La planta se actualizó correctamente.', 'success');
            plantaReset();
        }catch(e){
            showAlert('Error', e.message || 'No se pudo guardar la planta.', 'error');
            // deja habilitado el toggle / inputs para que el usuario corrija
        }
    });

